const crypto = require('crypto');

// Get input data
const input = $input.first().json.body;
const orderDataBase64 = input.orderData;
const domains = input.domains;
const email = input.email;

if (!orderDataBase64) {
  throw new Error('Order data is required');
}

// Decode order data
const orderData = JSON.parse(Buffer.from(orderDataBase64, 'base64').toString('utf-8'));

// Base64URL encode function
function base64url(input) {
  if (typeof input === 'string') {
    input = Buffer.from(input);
  }
  return input.toString('base64')
    .replace(/\+/g, '-')
    .replace(/\//g, '_')
    .replace(/=/g, '');
}

// Sign JWS with kid
function signJwsWithKid(payload, privateKeyPem, url, nonce, kid) {
  const header = {
    alg: 'RS256',
    kid: kid,
    nonce: nonce,
    url: url
  };

  const encodedHeader = base64url(JSON.stringify(header));
  const encodedPayload = payload === '' ? '' : base64url(JSON.stringify(payload));
  const signatureInput = `${encodedHeader}.${encodedPayload}`;

  const sign = crypto.createSign('RSA-SHA256');
  sign.update(signatureInput);
  const signature = sign.sign(privateKeyPem);

  return {
    protected: encodedHeader,
    payload: encodedPayload,
    signature: base64url(signature)
  };
}

return {
  json: {
    ...orderData,
    domains: domains,
    email: email,
    signJwsWithKid: signJwsWithKid.toString(),
    base64url: base64url.toString()
  }
};

