// Generate a proper CSR
function createCSR(domains, privateKeyPem) {
  const mainDomain = domains.find(d => !d.startsWith('*.')) || domains[0];

  // Create key object
  const privateKey = crypto.createPrivateKey(privateKeyPem);
  const publicKey = crypto.createPublicKey(privateKey);

  // Build CSR manually (simplified DER structure)
  // Version, Subject (CN), Public Key, Extensions (SAN), Signature

  // For Let's Encrypt, we need a proper PKCS#10 CSR
  // Using simplified approach with just the public key info

  const publicKeyDer = publicKey.export({ type: 'spki', format: 'der' });

  // Create a minimal CSR structure
  // This is a simplified version - in production use a proper library

  // Subject: CN=domain
  const cnOid = Buffer.from([0x55, 0x04, 0x03]); // 2.5.4.3 = CN
  const cnValue = Buffer.from(mainDomain);
  const cnSet = Buffer.concat([
    Buffer.from([0x31]), // SET
    encodeLength(2 + cnOid.length + 2 + cnValue.length + 4),
    Buffer.from([0x30]), // SEQUENCE
    encodeLength(cnOid.length + 2 + cnValue.length + 2),
    Buffer.from([0x06, cnOid.length]),
    cnOid,
    Buffer.from([0x0c, cnValue.length]), // UTF8String
    cnValue
  ]);

  const subject = Buffer.concat([
    Buffer.from([0x30]), // SEQUENCE
    encodeLength(cnSet.length),
    cnSet
  ]);

  // Subject Alternative Names extension
  const sanOid = Buffer.from([0x55, 0x1d, 0x11]); // 2.5.29.17 = SAN
  let sanValues = Buffer.alloc(0);
  for (const domain of domains) {
    const domainBuf = Buffer.from(domain);
    sanValues = Buffer.concat([
      sanValues,
      Buffer.from([0x82, domainBuf.length]), // DNS name (context tag 2)
      domainBuf
    ]);
  }

  const sanSeq = Buffer.concat([
    Buffer.from([0x30]),
    encodeLength(sanValues.length),
    sanValues
  ]);

  const sanExt = Buffer.concat([
    Buffer.from([0x30]),
    encodeLength(2 + sanOid.length + 2 + sanSeq.length),
    Buffer.from([0x06, sanOid.length]),
    sanOid,
    Buffer.from([0x04]),
    encodeLength(sanSeq.length),
    sanSeq
  ]);

  const extensions = Buffer.concat([
    Buffer.from([0xa0]), // Context tag 0 for extensions
    encodeLength(2 + sanExt.length + 2),
    Buffer.from([0x30]),
    encodeLength(sanExt.length + 2),
    Buffer.from([0x30]),
    encodeLength(sanExt.length),
    sanExt
  ]);

  // CSR Info
  const version = Buffer.from([0x02, 0x01, 0x00]); // INTEGER 0

  const csrInfo = Buffer.concat([
    Buffer.from([0x30]),
    encodeLength(version.length + subject.length + publicKeyDer.length + extensions.length),
    version,
    subject,
    publicKeyDer,
    extensions
  ]);

  // Sign the CSR
  const sign = crypto.createSign('RSA-SHA256');
  sign.update(csrInfo);
  const signature = sign.sign(privateKey);

  // Signature algorithm (SHA256 with RSA)
  const sigAlg = Buffer.from([
    0x30, 0x0d,
    0x06, 0x09, 0x2a, 0x86, 0x48, 0x86, 0xf7, 0x0d, 0x01, 0x01, 0x0b, // SHA256withRSA OID
    0x05, 0x00 // NULL
  ]);

  // Bit string for signature
  const sigBitString = Buffer.concat([
    Buffer.from([0x03]),
    encodeLength(signature.length + 1),
    Buffer.from([0x00]), // No unused bits
    signature
  ]);

  // Complete CSR
  const csr = Buffer.concat([
    Buffer.from([0x30]),
    encodeLength(csrInfo.length + sigAlg.length + sigBitString.length),
    csrInfo,
    sigAlg,
    sigBitString
  ]);

  return base64url(csr);
}

function encodeLength(len) {
  if (len < 128) {
    return Buffer.from([len]);
  } else if (len < 256) {
    return Buffer.from([0x81, len]);
  } else if (len < 65536) {
    return Buffer.from([0x82, (len >> 8) & 0xff, len & 0xff]);
  } else {
    return Buffer.from([0x83, (len >> 16) & 0xff, (len >> 8) & 0xff, len & 0xff]);
  }
}

